import 'dart:convert';

void main() {
  // A JSON data frame whose string value contains a multi-byte UTF-8 char
  // ("ã" = 0xC3 0xA3) right at a point we'll split across two "chunks".
  final payload = jsonEncode({'delta': 'informação'});
  final frame = 'event: token\ndata: $payload\n\n';
  final bytes = utf8.encode(frame);

  // Find the byte offset of the 2-byte char inside "informação" to split mid-sequence.
  // "informação" -> i n f o r m a ç ã o ; 'ã' encodes as 0xC3 0xA3.
  int splitPoint = -1;
  for (var i = 0; i < bytes.length - 1; i++) {
    if (bytes[i] == 0xC3 && bytes[i + 1] == 0xA3) {
      splitPoint = i + 1; // split right between the two bytes of 'ã'
      break;
    }
  }
  print('splitPoint=$splitPoint totalBytes=${bytes.length}');

  final chunk1 = bytes.sublist(0, splitPoint);
  final chunk2 = bytes.sublist(splitPoint);

  // Simulate ApiClient.sseStream's buggy per-chunk decode:
  final buffer = StringBuffer();
  buffer.write(utf8.decode(chunk1, allowMalformed: true));
  buffer.write(utf8.decode(chunk2, allowMalformed: true));
  final reconstructed = buffer.toString();
  print('reconstructed: $reconstructed');

  final dataLine = reconstructed.split('\n').firstWhere((l) => l.startsWith('data:'));
  final dataText = dataLine.substring(5).trim();
  print('dataText: $dataText');
  try {
    final decoded = jsonDecode(dataText);
    print('jsonDecode OK: $decoded');
  } catch (e) {
    print('jsonDecode FAILED: $e');
  }

  // Compare to correct behavior: decode the WHOLE byte buffer at once.
  final correct = utf8.decode(bytes, allowMalformed: true);
  print('correct (whole-buffer decode): ${correct.split('\n').firstWhere((l) => l.startsWith('data:'))}');
}
