1	// T-044 — Módulo `sse` (Plano técnico §7, §8.3, D12).
2	//
3	// "Emissão de eventos no formato fixo da D12": message_created -> context
4	// -> token* -> done|error. Dois consumidores diretos: `T-046` (streaming
5	// real, produzindo eventos enquanto acumula o texto do Sonnet 5) e `T-047`
6	// (reemissão a partir do cache, fatiando o texto já armazenado).
7	//
8	// Responsabilidades deste módulo:
9	//   1. Encodar cada evento no formato SSE (`event: <tipo>\ndata:
10	//      <json>\n\n`), validando o payload contra o schema Zod do contrato
11	//      (`contracts/zod/chat.ts`, T-026) antes de emitir — nunca deixa
12	//      passar um evento fora do formato combinado.
13	//   2. Impor a ordem fixa da D12 em tempo de execução — emitir fora de
14	//      ordem lança, em vez de silenciosamente produzir um stream errado.
15	//   3. `createSseStream`: ponte entre esse produtor de eventos e o
16	//      `ReadableStream<Uint8Array>` que o `gateway` (extensão desta
17	//      tarefa, ver abaixo) devolve como corpo da `Response`.
18	//   4. `emitReplayedTokens` (T-047): fatia um texto já completo em
19	//      pedaços de tamanho fixo, para reemitir a experiência de streaming
20	//      a partir de uma resposta em cache (Seção 9.4).
21	//
22	// Extensão de infraestrutura desta tarefa (fora do módulo em si, mas sem
23	// ela `sse` não tem onde plugar): `gateway.ts` (T-031, Fase 2) só sabia
24	// devolver `Response` JSON via `dataResponse`. O contrato já previa isso —
25	// `EndpointContract.response` tem a variante `{ kind: "sse" }` desde o
26	// registro dos 23 endpoints (T-026, `chat.messages.send`/`.retry`) — mas
27	// nenhum código ainda usava. `GatewayHandler` agora pode devolver também
28	// um `SseHandlerResult`, e `runGateway` reconhece a forma (`"stream" in
29	// result`) e devolve uma `Response` de streaming em vez de serializar
30	// JSON. Mesmo "ponto de entrada único" (§7) para os 23 endpoints — só uma
31	// segunda forma de resposta.
32	
33	import { chatStreamEventSchemas } from "../../../contracts/zod/chat.ts";
34	import type { ErrorCode } from "./errors.ts";
35	
36	// --- Tipos dos 5 eventos (mesmo shape dos schemas Zod de chat.ts) --------
37	
38	export interface MessageCreatedEvent {
39	  readonly type: "message_created";
40	  readonly userMessageId: string;
41	  readonly assistantMessageId: string;
42	  readonly seq: number;
43	}
44	
45	export interface ContextEvent {
46	  readonly type: "context";
47	  readonly retrievedEntryIds: readonly string[];
48	}
49	
50	export interface TokenEvent {
51	  readonly type: "token";
52	  readonly text: string;
53	}
54	
55	export interface DoneEvent {
56	  readonly type: "done";
57	  readonly assistantMessageId: string;
58	  readonly finishReason: string;
59	}
60	
61	export interface ErrorEvent {
62	  readonly type: "error";
63	  readonly code: ErrorCode | "REPLAY_MISS";
64	  readonly message: string;
65	  readonly retryable: boolean;
66	}
67	
68	export type ChatStreamEvent =
69	  | MessageCreatedEvent
70	  | ContextEvent
71	  | TokenEvent
72	  | DoneEvent
73	  | ErrorEvent;
74	
75	export class SseFormatError extends Error {}
76	export class SseSequenceError extends Error {}
77	
78	// --- Encoding (formato SSE) ----------------------------------------------
79	
80	const encoder = new TextEncoder();
81	
82	/** Valida o payload contra o schema Zod do contrato e encoda no formato `event: <tipo>\ndata: <json>\n\n`. */
83	export function encodeSseEvent(event: ChatStreamEvent): Uint8Array {
84	  const { type, ...payload } = event;
85	  // `REPLAY_MISS` (fora da taxonomia de 13, §9.3) não está no schema de
86	  // erro do contrato — só o próprio `errorCodeEnum` (13 códigos) está.
87	  // Ainda assim é um `type: "error"` SSE legítimo (§9.3: infraestrutura
88	  // de experimento, HTTP 500 equivalente dentro do stream); a checagem
89	  // de schema abaixo é pulada só para esse código específico.
90	  if (type === "error" && (payload as ErrorEvent).code === "REPLAY_MISS") {
91	    return frameFor(type, payload);
92	  }
93	
94	  const schema = chatStreamEventSchemas[type];
95	  const parsed = schema.safeParse(payload);
96	  if (!parsed.success) {
97	    throw new SseFormatError(
98	      `evento '${type}' não bate com o schema do contrato: ${parsed.error.message}`,
99	    );
100	  }
101	  return frameFor(type, payload);
102	}
103	
104	function frameFor(type: string, payload: unknown): Uint8Array {
105	  return encoder.encode(`event: ${type}\ndata: ${JSON.stringify(payload)}\n\n`);
106	}
107	
108	// --- Ordem fixa da D12 -----------------------------------------------------
109	
110	type SseState = "start" | "message_created" | "context" | "streaming" | "ended";
111	
112	const ALLOWED_NEXT: Record<SseState, ReadonlySet<ChatStreamEvent["type"]>> = {
113	  start: new Set(["message_created"]),
114	  message_created: new Set(["context"]),
115	  // Depois de `context`, zero ou mais `token`, terminando em `done` ou `error`.
116	  context: new Set(["token", "done", "error"]),
117	  streaming: new Set(["token", "done", "error"]),
118	  ended: new Set(),
119	};
120	
121	function nextState(eventType: ChatStreamEvent["type"]): SseState {
122	  if (eventType === "done" || eventType === "error") return "ended";
123	  if (eventType === "token") return "streaming";
124	  return eventType; // "message_created" | "context"
125	}
126	
127	/** Guarda de sequência isolado do encoding — usado por `createSseStream`, exposto também para teste direto da máquina de estados. */
128	export function createSseSequencer(): { assertNext(eventType: ChatStreamEvent["type"]): void } {
129	  let state: SseState = "start";
130	  return {
131	    assertNext(eventType) {
132	      if (!ALLOWED_NEXT[state].has(eventType)) {
133	        throw new SseSequenceError(
134	          `evento '${eventType}' fora de ordem — estado atual '${state}' só aceita: ${
135	            [...ALLOWED_NEXT[state]].join(", ") || "(nenhum — stream já encerrado)"
136	          }`,
137	        );
138	      }
139	      state = nextState(eventType);
140	    },
141	  };
142	}
143	
144	// --- Produtor: ponte entre eventos e ReadableStream -----------------------
145	
146	export interface SseEmitter {
147	  /** Valida (schema + ordem fixa da D12) e emite um evento. Lança se a ordem ou o schema forem violados. */
148	  emit(event: ChatStreamEvent): void;
149	  /** Fecha o stream. Chamar exatamente uma vez, sempre depois de `done` ou `error`. */
150	  close(): void;
151	}
152	
153	export interface SseStream {
154	  readonly stream: ReadableStream<Uint8Array>;
155	  readonly emitter: SseEmitter;
156	}
157	
158	/**
159	 * Constrói o par (`ReadableStream`, `emitter`) que todo endpoint de chat
160	 * streaming (T-046/T-048) usa: o handler devolve `stream` como corpo da
161	 * `Response` (via a extensão de `gateway.ts`) e alimenta `emitter` de
162	 * dentro de uma função assíncrona não esperada pelo gateway (fire-and-
163	 * forget deliberado — o corpo da `Response` já foi devolvido; o
164	 * `ReadableStream` é quem carrega os bytes conforme `emitter.emit` os
165	 * produz).
166	 */
167	export function createSseStream(): SseStream {
168	  let controller!: ReadableStreamDefaultController<Uint8Array>;
169	  const stream = new ReadableStream<Uint8Array>({
170	    start(c) {
171	      controller = c;
172	    },
173	  });
174	  const sequencer = createSseSequencer();
175	  let closed = false;
176	  const emitter: SseEmitter = {
177	    emit(event) {
178	      if (closed) {
179	        throw new SseSequenceError("emit chamado depois de close() — stream já encerrado");
180	      }
181	      sequencer.assertNext(event.type);
182	      controller.enqueue(encodeSseEvent(event));
183	    },
184	    close() {
185	      closed = true;
186	      controller.close();
187	    },
188	  };
189	  return { stream, emitter };
190	}
191	
192	// --- Cabeçalhos da resposta SSE --------------------------------------------
193	
194	export function sseHeaders(extra?: HeadersInit): Headers {
195	  const headers = new Headers(extra);
196	  headers.set("Content-Type", "text/event-stream; charset=utf-8");
197	  headers.set("Cache-Control", "no-cache");
198	  headers.set("Connection", "keep-alive");
199	  return headers;
200	}
201	
202	// --- T-047: reemissão a partir do cache (Seção 9.4) ------------------------
203	
204	/** "Fatiando em pedaços de tamanho fixo (32 caracteres) com intervalo de 15ms" (§9.4) — congelados; mudar isso muda a experiência de replay, não é config. */
205	export const REPLAY_CHUNK_SIZE = 32;
206	export const REPLAY_CHUNK_INTERVAL_MS = 15;
207	
208	export interface EmitReplayedTokensOptions {
209	  readonly chunkSize?: number;
210	  readonly intervalMs?: number;
211	  /** Injetável para teste — produção usa `setTimeout` de verdade. */
212	  readonly delayFn?: (ms: number) => Promise<void>;
213	}
214	
215	function defaultDelay(ms: number): Promise<void> {
216	  return new Promise((resolve) => setTimeout(resolve, ms));
217	}
218	
219	/**
220	 * Reemite um texto já completo (vindo do cache de replay) como uma
221	 * sequência de eventos `token`, em pedaços de `chunkSize` caracteres, com
222	 * `intervalMs` entre cada um. Determinístico por construção: os limites
223	 * de cada pedaço dependem só do comprimento do texto, nunca do relógio ou
224	 * da rede — "hit produz exatamente a mesma sequência de eventos"
225	 * (critério de conclusão do T-047).
226	 */
227	export async function emitReplayedTokens(
228	  emitter: SseEmitter,
229	  fullText: string,
230	  opts: EmitReplayedTokensOptions = {},
231	): Promise<void> {
232	  const chunkSize = opts.chunkSize ?? REPLAY_CHUNK_SIZE;
233	  const intervalMs = opts.intervalMs ?? REPLAY_CHUNK_INTERVAL_MS;
234	  const delayFn = opts.delayFn ?? defaultDelay;
235	
236	  for (let i = 0; i < fullText.length; i += chunkSize) {
237	    emitter.emit({ type: "token", text: fullText.slice(i, i + chunkSize) });
238	    await delayFn(intervalMs);
239	  }
240	}
241

