95	      responseSubscription.cancel();
96	      responseSink.close();
97	    },
98	    cancelOnError: true,
99	  );
100	
101	  options.cancelToken?.whenCancel.whenComplete(() {
102	    stopWatchReceiveTimeout();
103	    // Close the response stream upon a cancellation.
104	    response.close();
105	    responseSubscription.cancel();
106	    responseSink.addErrorAndClose(options.cancelToken!.cancelError!);
107	  });
108	  return responseSink.stream;
109	}
110	
111	extension on StreamController<Uint8List> {
112	  void addErrorAndClose(Object error, [StackTrace? stackTrace]) {
113	    if (!isClosed) {
114	      addError(error, stackTrace);
115	      close();
116	    }
117	  }
