// Temporary diagnostic test — NOT part of the suite, deleted after use.
// Spins up a real local HTTP server that emits an SSE stream shaped like a
// real (non-cached) Anthropic generation: message_created -> context ->
// many small token deltas trickling in over several real seconds -> done.
// Drives it through the REAL ApiClient with a REAL Dio/IOHttpClientAdapter
// (no mocks) to see whether the transport/parsing pipeline survives a
// slow, many-chunk response the way it needs to.
import 'dart:async';
import 'dart:convert';
import 'dart:io';

import 'package:cerne/core/network/api_client.dart';
import 'package:cerne/core/network/failure.dart';
import 'package:cerne/core/network/sse_frame.dart';
import 'package:cerne/core/storage/secure_token_storage.dart';
import 'package:dio/dio.dart';
import 'package:dio/io.dart';
import 'package:flutter_dotenv/flutter_dotenv.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:fpdart/fpdart.dart';
import 'package:mocktail/mocktail.dart';

class MockSecureTokenStorage extends Mock implements SecureTokenStorage {}

void main() {
  test('slow, many-chunk real-socket SSE stream parses end to end', () async {
    final server = await HttpServer.bind(InternetAddress.loopbackIPv4, 0);
    addTearDown(server.close);

    server.listen((request) async {
      request.response.headers.set('Content-Type', 'text/event-stream');
      request.response.bufferOutput = false;
      await request.response.flush();

      void writeEvent(String event, Map<String, dynamic> data) {
        request.response.write('event: $event\ndata: ${jsonEncode(data)}\n\n');
      }

      writeEvent('message_created', {
        'userMessageId': 'u-1',
        'assistantMessageId': 'a-1',
      });
      await request.response.flush();
      await Future<void>.delayed(const Duration(milliseconds: 50));

      writeEvent('context', {'retrievedEntryIds': <String>[]});
      await request.response.flush();
      await Future<void>.delayed(const Duration(milliseconds: 50));

      // ~9s of real token-by-token streaming, small deltas, each its own
      // flush -- mirrors how a live Anthropic stream actually arrives.
      final full = 'Esta é uma resposta de teste com acentuação em português: ação, não, café, informação, é, à, õ.';
      const chunkSize = 3;
      var accumulated = 0;
      final sw = Stopwatch()..start();
      for (var i = 0; i < full.length; i += chunkSize) {
        final delta = full.substring(i, (i + chunkSize).clamp(0, full.length));
        writeEvent('token', {'delta': delta});
        await request.response.flush();
        accumulated += delta.length;
        await Future<void>.delayed(const Duration(milliseconds: 90));
      }
      sw.stop();
      // ignore: avoid_print
      print('streamed $accumulated chars over ${sw.elapsedMilliseconds}ms');

      writeEvent('done', {
        'assistantMessageId': 'a-1',
        'content': full,
        'createdAt': DateTime.now().toIso8601String(),
      });
      await request.response.flush();
      await request.response.close();
    });

    dotenv.testLoad(fileInput: 'FUNCTIONS_BASE_URL=http://${server.address.address}:${server.port}');

    final dio = Dio()..httpClientAdapter = IOHttpClientAdapter();
    final tokenStorage = MockSecureTokenStorage();
    when(() => tokenStorage.readAccessToken()).thenAnswer((_) async => 'tok');
    final client = ApiClient(dio: dio, tokenStorage: tokenStorage, anonKey: 'anon');

    final results = <Either<Failure, SseFrame>>[];
    await client
        .sseStream('chat-messages-send', method: 'POST', body: const {'content': 'oi'})
        .forEach(results.add);

    // ignore: avoid_print
    print('total frames: ${results.length}');
    for (final r in results) {
      r.match(
        (f) => print('LEFT: ${f.runtimeType} ${f.message}'),
        (frame) => print('RIGHT: event=${frame.event} data=${frame.data}'),
      );
    }

    expect(results.every((r) => r.isRight()), isTrue, reason: 'expected no Left/failure frames');
    expect(results.last.getRight().toNullable()?.event, 'done');
  }, timeout: const Timeout(Duration(seconds: 30)));
}

