import 'package:flutter_dotenv/flutter_dotenv.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:mocktail/mocktail.dart';

class MockSecureTokenStorage extends Mock implements SecureTokenStorage {}

class MockChatRepository extends Mock implements ChatRepository {}

class MockConnectivityChecker extends Mock implements ConnectivityChecker {}

void main() {
  test('ChatBloc end-to-end over a real slow multi-chunk SSE socket', () async {
    final server = await HttpServer.bind(InternetAddress.loopbackIPv4, 0);
    addTearDown(server.close);

    server.listen((request) async {
      request.response.headers.set('Content-Type', 'text/event-stream');
      request.response.bufferOutput = false;
      await request.response.flush();

      void writeEvent(String event, Map<String, dynamic> data) {
        request.response.write('event: $event\ndata: ${jsonEncode(data)}\n\n');
      }

      writeEvent('message_created', {'userMessageId': 'u-1', 'assistantMessageId': 'a-1'});
      await request.response.flush();
      await Future<void>.delayed(const Duration(milliseconds: 50));
      writeEvent('context', {'retrievedEntryIds': <String>[]});
      await request.response.flush();
      await Future<void>.delayed(const Duration(milliseconds: 50));

      const full =
          'Esta eh uma resposta de teste bem mais longa, simulando um turno real de '
          'geracao token a token que demora varios segundos para terminar, exatamente '
          'como aconteceria com uma pergunta nova que nunca foi feita antes.';
      const chunkSize = 4;
      for (var i = 0; i < full.length; i += chunkSize) {
        final delta = full.substring(i, (i + chunkSize).clamp(0, full.length));
        writeEvent('token', {'delta': delta});
        await request.response.flush();
        await Future<void>.delayed(const Duration(milliseconds: 60));
      }

      writeEvent('done', {
        'assistantMessageId': 'a-1',
        'content': full,
        'createdAt': DateTime.now().toIso8601String(),
      });
      await request.response.flush();
      await request.response.close();
    });

    dotenv.loadFromString(
      envString: 'FUNCTIONS_BASE_URL=http://${server.address.address}:${server.port}',
    );

    final dio = Dio()..httpClientAdapter = IOHttpClientAdapter();
    final tokenStorage = MockSecureTokenStorage();
    when(() => tokenStorage.readAccessToken()).thenAnswer((_) async => 'tok');
    final apiClient = ApiClient(dio: dio, tokenStorage: tokenStorage, anonKey: 'anon');
    final remoteDataSource = ChatRemoteDataSource(apiClient);

    final chatRepository = MockChatRepository();
    final connectivityChecker = MockConnectivityChecker();
    final connectivityController = StreamController<bool>.broadcast();
    addTearDown(connectivityController.close);
    when(() => connectivityChecker.onConnectivityChanged)
        .thenAnswer((_) => connectivityController.stream);
    when(() => connectivityChecker.hasConnection()).thenAnswer((_) async => true);
    when(() => chatRepository.setLastActiveSessionId(any())).thenAnswer((_) async {});
    when(() => chatRepository.sendMessage(sessionId: any(named: 'sessionId'), content: any(named: 'content')))
        .thenAnswer(
      (invocation) => remoteDataSource.sendMessage(
        sessionId: invocation.namedArguments[#sessionId] as String,
        content: invocation.namedArguments[#content] as String,
      ),
    );

    final existingSession = ChatSession(
      id: 's1',
      title: 'title',
      personaSnapshot: ChatPersona.analitico,
      userMessageCount: 1,
      lastUserMessageAt: DateTime(2026, 1, 1),
      createdAt: DateTime(2026, 1, 1),
      updatedAt: DateTime(2026, 1, 1),
    );
    when(() => chatRepository.lastActiveSessionId).thenAnswer((_) async => existingSession.id);
    when(() => chatRepository.listMessages(existingSession.id)).thenAnswer(
      (_) async => Right([]),
    );
    when(() => chatRepository.cachedMessages(existingSession.id)).thenReturn(null);

    final bloc = ChatBloc(chatRepository: chatRepository, connectivityChecker: connectivityChecker);
    addTearDown(bloc.close);

    bloc.add(const ChatStarted());
    await Future<void>.delayed(Duration.zero);
    bloc.add(const MessageSubmitted('pergunta nova de teste'));

    await Future<void>.delayed(const Duration(seconds: 5));

    final state = bloc.state;
    expect(state, isA<ChatReady>());
    final ready = state as ChatReady;
    // ignore: avoid_print
    for (final m in ready.messages) {
      print('message id=${m.id} role=${m.role} status=${m.status} content=${m.content}');
    }
    final assistant = ready.messages.last;
    expect(assistant.role, ChatRole.assistant);
    expect(assistant.status, ChatMessageStatus.complete, reason: 'bubble ended up ${assistant.status} with content "${assistant.content}"');
  }, timeout: const Timeout(Duration(seconds: 30)));
}

