void main() {
  final rnd = Random(42);
  const fullAnswer =
      'Ação, não, café, informação, órgão, ímpar, política pública, '
      'saúde mental, relações humanas, ânimo, à toa, pôr, quê, três, '
      'está, não é, à beira, órbita, ônibus, único, água, pássaro.';

  var worstGarbled = 0;
  var totalTrials = 2000;
  var jsonFailures = 0;
  var eventOrderFailures = 0;

  for (var trial = 0; trial < totalTrials; trial++) {
    final sb = StringBuffer();
    sb.write(frame('message_created', {'userMessageId': 'u', 'assistantMessageId': 'a'}));
    sb.write(frame('context', {'retrievedEntryIds': <String>[]}));
    // split the full answer into token-sized deltas of random length 1-6 chars
    var i = 0;
