      final len = 1 + rnd.nextInt(6);
      final end = (i + len).clamp(0, fullAnswer.length);
      sb.write(frame('token', {'delta': fullAnswer.substring(i, end)}));
      i = end;
    }
    sb.write(frame('done', {'assistantMessageId': 'a', 'content': fullAnswer, 'createdAt': 'x'}));

    final allBytes = utf8.encode(sb.toString());

    // Simulate dio delivering this as a series of "network chunks" at
    // RANDOM byte boundaries (mimics real-world TCP/OS chunking).
    final chunks = <List<int>>[];
    var pos = 0;
    while (pos < allBytes.length) {
      final size = 1 + rnd.nextInt(40);
      final end = (pos + size).clamp(0, allBytes.length);
      chunks.add(allBytes.sublist(pos, end));
      pos = end;
    }

    // Replicate ApiClient.sseStream's buggy per-chunk decode + frame split.
    final buffer = StringBuffer();
    final frames = <(String, String)>[];
    for (final chunk in chunks) {
      buffer.write(utf8.decode(chunk, allowMalformed: true));
      var text = buffer.toString();
      while (text.contains('\n\n')) {
        final splitIndex = text.indexOf('\n\n');
        final raw = text.substring(0, splitIndex);
        text = text.substring(splitIndex + 2);
        String? ev;
        final dataLines = <String>[];
        for (final line in raw.split('\n')) {
          if (line.startsWith('event:')) {
            ev = line.substring(6).trim();
          } else if (line.startsWith('data:')) {
            dataLines.add(line.substring(5).trim());
          }
        }
        if (ev != null) frames.add((ev, dataLines.join('\n')));
      }
      buffer..clear()..write(text);
    }

    // Now replicate _mapFrame's jsonDecode per frame.
    var replacementCount = 0;
    for (final (event, data) in frames) {
      replacementCount += data.runes.where((r) => r == 0xFFFD).length;
      try {
        final decoded = jsonDecode(data);
        if (event == 'message_created') {
          decoded['userMessageId'] as String;
          decoded['assistantMessageId'] as String;
        } else if (event == 'token') {
          decoded['delta'] as String;
        } else if (event == 'done') {
          decoded['assistantMessageId'] as String;
          decoded['content'] as String;
        }
      } catch (e) {
        jsonFailures++;
        print('trial $trial: JSON/TypeError on event=$event data=${jsonEncode(data)}: $e');
      }
    }
    if (replacementCount > worstGarbled) worstGarbled = replacementCount;

    // Check event ordering matches expected sequence shape.
    final eventTypes = frames.map((f) => f.$1).toList();
    if (eventTypes.isEmpty || eventTypes.first != 'message_created' || eventTypes.last != 'done') {
      eventOrderFailures++;
      print('trial $trial: bad ordering: $eventTypes');
    }
  }

  print('trials=$totalTrials jsonFailures=$jsonFailures eventOrderFailures=$eventOrderFailures worstGarbledCharsInOneTrial=$worstGarbled');
}
