    if (eventTypes.isEmpty || eventTypes.first != 'message_created' || eventTypes.last != 'done') {
      eventOrderFailures++;
      print('trial $trial: bad ordering: $eventTypes');
    }
  }

  print('trials=$totalTrials jsonFailures=$jsonFailures eventOrderFailures=$eventOrderFailures worstGarbledCharsInOneTrial=$worstGarbled');
}
