1	// T-032 — Cliente `ai/anthropic` (Plano técnico §7): "Cliente Sonnet 5 e
2	// Haiku 4.5, sempre atrás do cache."
3	//
4	// Este módulo é deliberadamente genérico — não sabe se está servindo
5	// detecção de PII (T-036, Fase 3), geração de insight (T-050, Fase 4) ou
6	// chat (T-046, Fase 4). Quem monta o `envelope` (via os builders de
7	// `replay.ts`, T-030) e o `request` (mensagens, prompt de sistema,
8	// ferramentas) é o módulo de negócio de cada operação — nunca esta camada.
9	// A única garantia que este módulo dá é estrutural: a chamada real à
10	// Anthropic *nunca* acontece fora de `withReplay`.
11	
12	import {
13	  type CanonicalEnvelope,
14	  type ReplayDeps,
15	  type ReplayResult,
16	  withReplay,
17	} from "../replay.ts";
18	
19	/** Os dois modelos que este cliente atende (§7) — nenhum outro é aceito por convenção do projeto. */
20	export const ANTHROPIC_MODELS = {
21	  sonnet5: "claude-sonnet-5",
22	  haiku45: "claude-haiku-4-5-20251001",
23	} as const;
24	
25	/** Bloco de conteúdo multimodal (T-041, OCR via visão) — mesmo formato da Messages API. */
26	export interface AnthropicTextContent {
27	  readonly type: "text";
28	  readonly text: string;
29	}
30	
31	export interface AnthropicImageContent {
32	  readonly type: "image";
33	  readonly source: {
34	    readonly type: "base64";
35	    readonly media_type: string;
36	    readonly data: string;
37	  };
38	}
39	
40	export type AnthropicContentInput = AnthropicTextContent | AnthropicImageContent;
41	
42	export interface AnthropicMessage {
43	  readonly role: "user" | "assistant";
44	  /** String para texto puro (chat, PII) — array de blocos para conteúdo multimodal (OCR, T-041). */
45	  readonly content: string | readonly AnthropicContentInput[];
46	}
47	
48	export interface AnthropicRequest {
49	  readonly model: string;
50	  readonly system?: string;
51	  readonly messages: readonly AnthropicMessage[];
52	  readonly maxTokens: number;
53	  /** Definição de ferramenta no formato da Messages API — usado pela detecção de PII (tool use). */
54	  readonly tools?: readonly unknown[];
55	  readonly toolChoice?: unknown;
56	}
57	
58	export interface AnthropicContentBlock {
59	  readonly type: string;
60	  readonly text?: string;
61	  readonly id?: string;
62	  readonly name?: string;
63	  readonly input?: unknown;
64	}
65	
66	export interface AnthropicResponse {
67	  readonly id: string;
68	  readonly model: string;
69	  readonly content: readonly AnthropicContentBlock[];
70	  readonly stopReason: string | null;
71	}
72	
73	/**
74	 * A Anthropic respondeu algo que não é 2xx, ou um corpo que não parece a
75	 * Messages API. Deliberadamente não é um `CerneError`: qual dos 13
76	 * códigos isso vira (`PII_CHECK_FAILED`, `AI_GENERATION_TIMEOUT`, ...)
77	 * depende de qual operação estava chamando — decisão do módulo de
78	 * negócio (Fase 3/4), não deste cliente genérico.
79	 */
80	export class AnthropicApiError extends Error {
81	  readonly status: number;
82	  readonly body: unknown;
83	  constructor(status: number, body: unknown, message?: string) {
84	    super(message ?? `Anthropic API respondeu ${status}`);
85	    this.name = "AnthropicApiError";
86	    this.status = status;
87	    this.body = body;
88	  }
89	}
90	
91	export interface AnthropicEnv {
92	  readonly anthropicApiKey: string;
93	  /** Injetável para teste — produção usa `fetch` de verdade. */
94	  readonly fetchImpl?: typeof fetch;
95	}
96	
97	const ANTHROPIC_API_URL = "https://api.anthropic.com/v1/messages";
98	const ANTHROPIC_VERSION = "2023-06-01";
99	
100	/**
101	 * `fetch` não tem timeout próprio — sem um `signal`, uma chamada que trava
102	 * na rede (DNS, egress bloqueado, conexão que nunca fecha) nunca falha
103	 * sozinha; ela fica pendurada até o teto externo do runtime matar o
104	 * isolate inteiro. No `supabase functions serve` local isso aparece nos
105	 * logs como "wall clock duration warning" seguido de "early termination
106	 * has been triggered" — não um erro do envelope do projeto (§3.2), e sim
107	 * o motor de Edge Functions abortando à força. Achado rodando de verdade
108	 * (`media_ocr.hurl`, T-041): as sub-requisições que nunca chegam a chamar
109	 * a Anthropic (401 sem token, 413 de imagem grande demais) respondem na
110	 * hora; só as duas que chegam aqui (imagem ilegível, caminho feliz)
111	 * travavam. Com o `signal`, uma chamada presa falha em
112	 * `ANTHROPIC_REQUEST_TIMEOUT_MS` com um erro normal — o `catch` de
113	 * `performOcr` (media-ocr/ocr.ts) já converte isso em
114	 * `AI_GENERATION_TIMEOUT`.
115	 */
116	export const ANTHROPIC_REQUEST_TIMEOUT_MS = 30_000;
117	
118	async function callAnthropicRaw(
119	  request: AnthropicRequest,
120	  env: AnthropicEnv,
121	): Promise<AnthropicResponse> {
122	  const fetchFn = env.fetchImpl ?? fetch;
123	  const res = await fetchFn(ANTHROPIC_API_URL, {
124	    method: "POST",
125	    headers: {
126	      "Content-Type": "application/json",
127	      "x-api-key": env.anthropicApiKey,
128	      "anthropic-version": ANTHROPIC_VERSION,
129	    },
130	    body: JSON.stringify({
131	      model: request.model,
132	      system: request.system,
133	      messages: request.messages,
134	      max_tokens: request.maxTokens,
135	      tools: request.tools,
136	      tool_choice: request.toolChoice,
137	    }),
138	    signal: AbortSignal.timeout(ANTHROPIC_REQUEST_TIMEOUT_MS),
139	  });
140	
141	  const body = await res.json();
142	  if (!res.ok) throw new AnthropicApiError(res.status, body);
143	
144	  return {
145	    id: body.id,
146	    model: body.model,
147	    content: Array.isArray(body.content) ? body.content : [],
148	    stopReason: body.stop_reason ?? null,
149	  };
150	}
151	
152	/**
153	 * Chama Sonnet 5/Haiku 4.5 atrás do cache de replay. Em `REPLAY_MODE`
154	 * `record`/`replay`, uma segunda chamada com o mesmo `envelope` nunca
155	 * bate na rede — devolve `status: 'hit'` a partir do cache.
156	 */
157	export function callAnthropic(
158	  envelope: CanonicalEnvelope,
159	  request: AnthropicRequest,
160	  deps: AnthropicEnv & { replay: ReplayDeps },
161	): Promise<ReplayResult<AnthropicResponse>> {
162	  return withReplay(envelope, () => callAnthropicRaw(request, deps), deps.replay);
163	}
164	
165	// --- Streaming (T-046, Fase 4) ---------------------------------------------
166	//
167	// `callAnthropic` (acima) espera o JSON completo — suficiente para PII
168	// (T-036) e OCR (T-041), que só precisam do resultado final de uma
169	// chamada com tool use. O chat (`POST .../messages`, §8.3 passo 6-7)
170	// precisa emitir eventos `token` conforme o Sonnet 5 gera, então não pode
171	// esperar a resposta inteira: `streamAnthropic` chama a Messages API com
172	// `stream: true` e entrega cada pedaço de texto via `onDelta` assim que
173	// chega, devolvendo o texto completo (para gravar no cache, §9.4) só no
174	// final.
175	//
176	// Deliberadamente FORA de `withReplay`/`callAnthropic`: quem orquestra o
177	// cache aqui é o próprio handler de chat (`chat-messages-send/generation.ts`),
178	// não este cliente — o motivo é que o header `X-Replay-Status` precisa
179	// ser decidido *antes* dos bytes da `Response` SSE começarem a sair (a
180	// própria decisão de fazer streaming real vs. reemissão fatiada do cache,
181	// T-047, depende de saber hit/miss primeiro), o que o formato "espera
182	// tudo, devolve status no final" de `withReplay` não permite.
183	
184	export interface AnthropicStreamResult {
185	  readonly text: string;
186	  readonly stopReason: string | null;
187	}
188	
189	/** Chamado a cada pedaço de texto novo (`content_block_delta`) conforme chega da Anthropic. */
190	export type OnTextDelta = (text: string) => void;
191	
192	interface SseFrame {
193	  readonly event: string;
194	  // deno-lint-ignore no-explicit-any
195	  readonly data: any;
196	}
197	
198	/** Um frame SSE cru (`event: <tipo>\ndata: <json>`) da própria Anthropic — não confundir com o formato de `sse.ts` (T-044), que é o que ESTE servidor emite para o app, um nível acima. */
199	function parseAnthropicSseFrame(frame: string): SseFrame | null {
200	  let event = "message";
201	  const dataLines: string[] = [];
202	  for (const line of frame.split("\n")) {
203	    if (line.startsWith("event:")) event = line.slice("event:".length).trim();
204	    else if (line.startsWith("data:")) dataLines.push(line.slice("data:".length).trim());
205	  }
206	  if (dataLines.length === 0) return null;
207	  try {
208	    return { event, data: JSON.parse(dataLines.join("\n")) };
209	  } catch {
210	    return null;
211	  }
212	}
213	
214	async function callAnthropicStreamRaw(
215	  request: AnthropicRequest,
216	  env: AnthropicEnv,
217	  onDelta: OnTextDelta,
218	): Promise<AnthropicStreamResult> {
219	  const fetchFn = env.fetchImpl ?? fetch;
220	  const res = await fetchFn(ANTHROPIC_API_URL, {
221	    method: "POST",
222	    headers: {
223	      "Content-Type": "application/json",
