// Temporary verification test — NOT part of the suite, deleted after use.
import 'dart:async';
import 'dart:convert';
import 'dart:io';

import 'package:cerne/core/network/api_client.dart';
import 'package:cerne/core/network/failure.dart';
import 'package:cerne/core/network/sse_frame.dart';
import 'package:cerne/core/storage/secure_token_storage.dart';
import 'package:dio/dio.dart';
import 'package:dio/io.dart';
import 'package:flutter_dotenv/flutter_dotenv.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:fpdart/fpdart.dart';
import 'package:mocktail/mocktail.dart';

class MockSecureTokenStorage extends Mock implements SecureTokenStorage {}

void main() {
  test('accented Portuguese text survives a chunk split without corruption', () async {
    final server = await HttpServer.bind(InternetAddress.loopbackIPv4, 0);
    addTearDown(server.close);

    const full = 'Esta é uma resposta de teste com acentuação em português: ação, não, café, informação, é, à, õ.';

    server.listen((request) async {
      request.response.headers.set('Content-Type', 'text/event-stream');
      request.response.bufferOutput = false;
      await request.response.flush();
      const chunkSize = 3;
      for (var i = 0; i < full.length; i += chunkSize) {
        final delta = full.substring(i, (i + chunkSize).clamp(0, full.length));
        request.response.write('event: token\ndata: ${jsonEncode({'text': delta})}\n\n');
        await request.response.flush();
      }
      await request.response.close();
    });

    dotenv.loadFromString(
      envString: 'FUNCTIONS_BASE_URL=http://${server.address.address}:${server.port}',
    );
    final dio = Dio()..httpClientAdapter = IOHttpClientAdapter();
    final tokenStorage = MockSecureTokenStorage();
    when(() => tokenStorage.readAccessToken()).thenAnswer((_) async => 'tok');
    final client = ApiClient(dio: dio, tokenStorage: tokenStorage, anonKey: 'anon');

    final results = <Either<Failure, SseFrame>>[];
    await client.sseStream('chat-messages-send', method: 'POST').forEach(results.add);

    final reconstructed = results.map((r) {
      final frame = r.getRight().toNullable()!;
      return (jsonDecode(frame.data) as Map<String, dynamic>)['text'] as String;
    }).join();

    print('reconstructed: $reconstructed');
    expect(reconstructed, full);
  }, timeout: const Timeout(Duration(seconds: 15)));
}

